+        margin: 0;
+        max-width: 58ch;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.6;
+      }
+
+      .faq {
+        display: grid;
+        gap: 14px;
+        margin-top: 32px;
+      }
+
+      .example {
+        border: 1px solid var(--panel-border);
+        border-radius: 20px;
+        background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(10, 15, 31, 0.96));
+        box-shadow: var(--shadow);
+        overflow: hidden;
+      }
+
+      .question {
+        width: 100%;
+        appearance: none;
+        border: 0;
+        background: transparent;
+        color: var(--text);
+        text-align: left;
+        padding: 20px 22px;
+        font: inherit;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 18px;
+        cursor: pointer;
+      }
+
+      .question:focus-visible {
+        outline: 3px solid rgba(139, 92, 246, 0.55);
+        outline-offset: -3px;
+      }
+
+      .question-title {
+        font-size: 1.04rem;
+        font-weight: 650;
+        line-height: 1.45;
+      }
+
+      .toggle {
+        flex: none;
+        width: 34px;
+        height: 34px;
+        border-radius: 999px;
+        display: grid;
+        place-items: center;
+        background: var(--accent-soft);
+        color: #ddd6fe;
+        transition: transform 180ms ease, background 180ms ease;
+      }
+
+      .example[data-open="true"] .toggle {
+        transform: rotate(45deg);
+        background: rgba(139, 92, 246, 0.3);
+      }
+
+      .details {
+        padding: 0 22px 20px;
+        color: var(--muted);
+        line-height: 1.75;
+        overflow: hidden;
+        max-height: 0;
+        opacity: 0;
+        transition: max-height 240ms ease, opacity 200ms ease;
+      }
+
+      .example[data-open="true"] .details {
+        max-height: 220px;
+        opacity: 1;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100vw - 24px, 920px);
+          padding-top: 28px;
+        }
+
+        .question {
+          padding: 18px 18px;
+        }
+
+        .details {
+          padding: 0 18px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page" id="app" aria-label="Cat FAQ"></main>
+
+    <script>
+      const faqData = [
+        {
+          question: "Why do cats purr?",
+          answer:
+            "Cats often purr when they are relaxed and comfortable, but they may also purr to self-soothe or communicate that they want attention."
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer:
+            "Most adult cats sleep around 12 to 16 hours a day, and kittens or senior cats can sleep even more."
+        },
+        {
+          question: "Why do cats knead blankets or laps?",
+          answer:
+            "Kneading is a comforting behavior that starts in kittenhood. Many cats keep doing it as a sign of contentment and security."
+        },
+        {
+          question: "Do indoor cats need exercise?",
+          answer:
+            "Yes. Play sessions, climbing space, and puzzle feeders help indoor cats stay fit, mentally engaged, and less bored."
+        }
+      ];
+
+      function FAQItem({ question, answer, index }) {
+        const contentId = `faq-answer-${index}`;
+        return `
+          <div class="example" data-open="false">
+            <button
+              class="question"
+              type="button"
+              aria-expanded="false"
+              aria-controls="${contentId}"
+            >
+              <span class="question-title">${question}</span>
+              <span class="toggle" aria-hidden="true">+</span>
+            </button>
+            <div class="details" id="${contentId}" hidden>
+              <p>${answer}</p>
+            </div>
+          </div>
+        `;
+      }
+
+      function App() {
+        return `
+          <section class="hero">
+            <div class="eyebrow">Cat FAQ</div>
+            <h1>Everything you wanted to know about cats</h1>
+            <p class="subtitle">
+              A compact, dark-themed FAQ with expandable answers and keyboard-friendly controls.
+            </p>
+          </section>
+          <section class="faq" aria-label="Frequently asked questions">
+            ${faqData.map((item, index) => FAQItem({ ...item, index })).join("")}
+          </section>
+        `;
+      }
+
+      const app = document.getElementById("app");
+      app.innerHTML = App();
+
+      app.addEventListener("click", (event) => {
+        const button = event.target.closest(".question");
+        if (!button) return;
+
+        const card = button.closest(".example");
