        --accent: #8b5cf6;
        --accent-soft: rgba(139, 92, 246, 0.18);
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(139, 92, 246, 0.18), transparent 30%),
          linear-gradient(180deg, #050816 0%, var(--bg) 100%);
        color: var(--text);
      }

      .page {
        width: min(920px, calc(100vw - 32px));
        margin: 0 auto;
        padding: 56px 0 72px;
      }

      .hero {
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 14px;
        padding: 8px 12px;
        border: 1px solid var(--panel-border);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.04);
        color: var(--muted);
        font-size: 0.875rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 10px;
        font-size: clamp(2.4rem, 4vw, 4rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 58ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .faq {
        display: grid;
        gap: 14px;
        margin-top: 32px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(10, 15, 31, 0.96));
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .question {
        width: 100%;
        appearance: none;
        border: 0;
        background: transparent;
        color: var(--text);
        text-align: left;
        padding: 20px 22px;
        font: inherit;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 18px;
        cursor: pointer;
      }

      .question:focus-visible {
        outline: 3px solid rgba(139, 92, 246, 0.55);
        outline-offset: -3px;
      }

      .question-title {
        font-size: 1.04rem;
        font-weight: 650;
        line-height: 1.45;
      }

      .toggle {
        flex: none;
        width: 34px;
        height: 34px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: var(--accent-soft);
        color: #ddd6fe;
        transition: transform 180ms ease, background 180ms ease;
      }

      .example[data-open="true"] .toggle {
        transform: rotate(45deg);
        background: rgba(139, 92, 246, 0.3);
      }

      .details {
        padding: 0 22px 20px;
        color: var(--muted);
        line-height: 1.75;
        overflow: hidden;
        max-height: 0;
        opacity: 0;
        transition: max-height 240ms ease, opacity 200ms ease;
      }

      .example[data-open="true"] .details {
        max-height: 220px;
        opacity: 1;
      }

      .details p {
        margin: 0;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100vw - 24px, 920px);
          padding-top: 28px;
        }

        .question {
          padding: 18px 18px;
        }

        .details {
          padding: 0 18px 18px;
        }
      }
